    "unitId": "n1:task-comprehension:2016-12:5:line-7",
    "text": "時給が高いに越したことはないですが、必ずしもそれが仕事をやめる原因となるわけではないんですよ。あとは、仕事の作業項目ごとに習熟度を定期的に評価して、アルバイトの人自身が成長を実感できるようにすると、モチベーションが上がっていいですよ。",
